    throw new RangeError(`readingTimeMinutes: wpm must be a positive finite number, received ${String(wpm)}`);
  }
  return Math.ceil(wordCount(text) / wpm);
}

module.exports = { wordCount, sentenceCount, topWords, readingTimeMinutes };
